var description = new Array();
description[0] = "<tbody><tr><td><p>Decreto 1457 de 2020; Art. <A href='decreto_1457_2020.htm#3' >3</A>; Art. <A href='decreto_1457_2020.htm#4' >4</A> (DUR 1625; Art. <A href='decreto_1625_2016.htm#1.2.1.10.4' >1.2.1.10.4</A>; Art. <A href='decreto_1625_2016.htm#1.2.1.10.5' >1.2.1.10.5</A>; Art. <A href='decreto_1625_2016.htm#1.2.4.7.3' >1.2.4.7.3</A>; Art. <A href='decreto_1625_2016.htm#1.2.4.7.8' >1.2.4.7.8</A>; Art. <A href='decreto_1625_2016.htm#1.2.4.7.9' >1.2.4.7.9</A>) </p><p>Decreto 2371 de 2019; Art. <A href='decreto_2371_2019.htm#3' >3</A>; Art. <A href='decreto_2371_2019.htm#4' >4</A> (DUR 1625; Art. <A href='decreto_1625_2016.htm#1.2.1.10.4' >1.2.1.10.4</A>; Art. <A href='decreto_1625_2016.htm#1.2.1.10.5' >1.2.1.10.5</A>; Art. <A href='decreto_1625_2016.htm#1.2.4.7.3' >1.2.4.7.3</A>; Art. <A href='decreto_1625_2016.htm#1.2.4.7.8' >1.2.4.7.8</A>; Art. <A href='decreto_1625_2016.htm#1.2.4.7.9' >1.2.4.7.9</A>) </p><p>Decreto <A href='decreto_1157_2020.htm#inicio' >1157</A> de 2020 (DUR 1625; <A href='decreto_1625_2016.htm#Secci&oacute;n 1.2.1.28.1' >Secci&oacute;n 1.2.1.28.1</A>) </p> </td></tr></tbody>";
var z=document.getElementById('Table1805').rows[0];
