description[0] = "<tbody><tr><td><p>Concepto DIAN <A href='oficio_dian_10813_2024.htm#0' >10813</A> de 2024</p><p>Concepto DIAN <A href='oficio_dian_2703_2024.htm#0' >2703</A> de 2024</p><p>Concepto DIAN <A href='oficio_dian_1961_2024.htm#INICIO' >1961</A> de 2024</p><p>Oficio DIAN <A href='oficio_dian_906156_2022.htm#INICIO' >906156</A> de 2022</p><p>Oficio DIAN <A href='oficio_dian_902024_2022.htm#INICIO' >902024</A> de 2022</p><p>Concepto DIAN <A href='concepto_tributario_dian_0071403_2013.htm#inicio' >71403</A> de 2013 </p><p>Oficio DIAN <A href='oficio_dian_94487_2009.htm#1' >94487</A> de 2009 </p><p>Oficio DIAN <A href='oficio_dian_97288_2005.htm#1' >97288</A> de 2005</p><p>Oficio DIAN <A href='oficio_dian_76417_2005.htm#1' >76417</A> de 2005</p> </td></tr></tbody>";
