function insRow5103()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Texto original del Estatuto Tributario:</span></p><p>DECLARACI&Oacute;N DE TIMBRE </p><p>ART&Iacute;CULO 607. QUI&Eacute;NES DEBEN PRESENTAR DECLARACI&Oacute;N. A partir del 1&ordm; de febrero de 1988, las personas o entidades que realicen actuaciones sometidas al impuesto de timbre, deber&aacute;n presentar una declaraci&oacute;n por los documentos y actos sometidos a dicho gravamen. La obligaci&oacute;n de presentar la declaraci&oacute;n recae sobre las personas o entidades, que de conformidad con las normas vigentes, sean contribuyentes de dicho impuesto, o agentes de retenci&oacute;n del mismo, seg&uacute;n el caso. La presentaci&oacute;n de la declaraci&oacute;n por una cualquiera de las partes libera a las dem&aacute;s de esta obligaci&oacute;n.</p> </td></tr></tbody>";
var z=document.getElementById('Table5103').rows[0];
if (z==null) {
	var x=document.getElementById('Table5103').insertRow(0);
	var y=x.insertCell(0);
	y.innerHTML=description;
	document.getElementById('Table5103').style.display = "block";
	}
else {
	document.getElementById('Table5103').deleteRow(0);
	document.getElementById('Table5103').style.display = "none";
	}
}
